window.RP_SESSION={"id":"S-d0224128eaef","messages":[{"id":"RP-0088516","time":"2026-03-26T00:08:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"햇볕이 내리쬐는 한낮.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088517","time":"2026-03-26T00:09:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"따스한 꿈결서 피어나\n아스란 잠결에 부스럭이는\n보드란 풀결을 어루만지고","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088518","time":"2026-03-26T00:09:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"점점으로 내리우는 볕결에 눈을 부시며","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088519","time":"2026-03-26T00:10:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"엘타리온은 달큰한 낮잠에서 깨어난다.","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088520","time":"2026-03-26T00:10:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"새소리, 바람 소리","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088521","time":"2026-03-26T00:11:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"먹먹한 졸리움에 맺히질 않아","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088522","time":"2026-03-26T00:12:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린의 살결에\n하늘한 털결에 머리를 맞대어 눕고","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088523","time":"2026-03-26T00:12:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"다시 눈을 감는다...","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088524","time":"2026-03-26T00:26:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"네레이드의 쓰다듬을받으며 엘타리온과는 반대방향에서 낮잠을자던 리엔~","characters":["P-a161473e74e0"]},{"id":"RP-0088525","time":"2026-03-26T00:28:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"엘타리온씨, 얼마나잤죠?\"\n\n정신을 차려보니 해가 저물어가고, 낮잠을너무 오래잤나봐~ 싶은순간. 같이 얘기나누다가 잠든 엘타리온을발견하고 깨웁니다!\n\n\"일어나봐요, 이러다가 정작밤에 못자겠어요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0088526","time":"2026-03-26T00:31:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 세 시간. 아니, 네 시간일까? \"\n\n석양은 붉은 혓바닥을 놀리며 마당의 푸르른 잔디를 핥는다. 끈덕진 땅거미가 흙바닥에 스며들면 빛결은 땅과 수평이 된다. 거인 같은 그림자가 나타나는 시간에 엘타리온. 그녀는 눈을 뜬다.\n\n\" 중요하지 않아. 리엔 군. 스승님이 내게 과제를 주셨어. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088527","time":"2026-03-26T00:32:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 폴라리스 언니는 엘프들에게 가장 많은게 시간이라고 했어. 멜라니온 스승님도 마찬가지고. 시간은 도대체 뭘까? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088528","time":"2026-03-26T00:33:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 시간이라는게 그렇게 쓸모가 많고, 또 유용하다면. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088529","time":"2026-03-26T00:33:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 시간을 잔뜩 가진 엘프들은 왜 실패하고, 부서지고, 깨지는걸까? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088530","time":"2026-03-26T00:33:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그 시간을 잔뜩 팔거나, 쓰거나, 날려버리면. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088531","time":"2026-03-26T00:34:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 무슨 일이든 할 수 있을텐데. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088532","time":"2026-03-26T00:35:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그 정답을알아오는게 과제인가요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0088533","time":"2026-03-26T00:36:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 응. 시간... 시간... \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088534","time":"2026-03-26T00:37:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 솔직히, 스승님은 700살이시고, 나는 겨우 92살이잖아. 거쳐 온 시간의 단위가 다른데 내가 그 분을 만족 시킬 수 있을 만 한 답을 내놓을 수 있을까? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088535","time":"2026-03-26T00:38:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"엘타리온씨라면 할수있어요. 저는믿어요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0088536","time":"2026-03-26T00:40:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 리엔 군. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088537","time":"2026-03-26T00:41:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 시간 속에 혼자 남겨진다는건 원래 무섭고 쓸쓸하고 서러운거지? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088538","time":"2026-03-26T00:41:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 나만 시간이 무서운게 아니지? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088539","time":"2026-03-26T00:42:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"저는... 시간이 무섭지않아요. 결국우린 나아가게 되어있는걸요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0088540","time":"2026-03-26T00:42:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 결국 나아가게 되어 있다고... \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088541","time":"2026-03-26T00:43:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 난 그 점에서 무서운건데. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088542","time":"2026-03-26T00:43:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아무리 머물러 있고 싶어 해도 끌려 간다는거잖아. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088543","time":"2026-03-26T00:44:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 세 시간을 잤는지 네 시간을 잤는지, 열 시간을 잤다 해도. 시간은 멈추지 않고 우리를 계속 미래로 끌고 간다는거잖아. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088544","time":"2026-03-26T00:44:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 왜 무섭지 않은거야? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088545","time":"2026-03-26T00:45:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"글쎄요, 제가 인간의수명을 가지는 하프엘프라서 그런걸지도모르지만~\"","characters":["P-a161473e74e0"]},{"id":"RP-0088546","time":"2026-03-26T00:45:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"언젠가는 끝난다는사실이, 역으로 위로가될때가 있어요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0088547","time":"2026-03-26T00:46:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 왜? 어째서? 우리는 결국 피할 수 없는 파멸을 맞는다는 뜻이잖아. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088548","time":"2026-03-26T00:48:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그건 시간이 더 무섭다는 뜻 아니야? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088549","time":"2026-03-26T00:48:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"글쎄요, 파멸은 피할수없기에 시간이란 더더욱이 가치있는것 아닐까요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0088550","time":"2026-03-26T00:49:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그렇다면. 시간을 잔뜩 가진 이들은 왜 실패하는걸까? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088551","time":"2026-03-26T00:50:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"저는 시간이라는게 돈같이 바로바로 교환할수있는 가치가아니라, 실패하고, 부서지고, 깨지고, 넘어지더라도 다시일어설수있는 기회를주는 가치라고 생각이드네요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0088552","time":"2026-03-26T00:50:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"멜라니온씨가 그런의도로 문제를내셨다면, 그런뜻일지도 몰라요. 저도 잘은 모르는문제지만요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0088553","time":"2026-03-26T00:51:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 기회...? \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088554","time":"2026-03-26T00:52:00+09:00","room":"RP","name":"리엔 에이라스 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"저는 길드로 돌아가봐야겠어요. 다음에 또뵈어요!\"","characters":["P-a161473e74e0"]},{"id":"RP-0088555","time":"2026-03-26T00:53:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그래요, 다음에 또 뵈어요. \"","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088556","time":"2026-03-26T00:53:00+09:00","room":"RP","name":"엘타리온 / 린","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-cf2651679b0b","P-cf90597a7c66"]},{"id":"RP-0088557","time":"2026-03-26T00:53:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
